# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score

import random

# Constants
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
NUM_CLASSES = 206  # Number of unique bird species in the training dataset

class BirdCLEFModel(nn.Module):
    def __init__(self, num_classes, conv_layers=3, dropout_rate=0.5):
        super(BirdCLEFModel, self).__init__()
        layers = []
        channels = [1, 64]
        for i in range(conv_layers - 1):
            layers.append(nn.Conv2d(channels[-1], channels[-1] * 2, kernel_size=3, padding=1))
            layers.append(nn.BatchNorm2d(channels[-1] * 2))
            layers.append(nn.ReLU())
            channels.append(channels[-1] * 2)
        
        layers.append(nn.Conv2d(channels[-1], channels[-1], kernel_size=3, padding=1))
        layers.append(nn.ReLU())
        
        self.conv_layers = nn.Sequential(*layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Dropout(dropout_rate),
            nn.Linear(channels[-1], 512),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(512, num_classes)
        )

    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

def train_model(iteration):
    # Hyperparameters based on iteration number
    batch_size_options = {0: 8, 1: 16, 2: 32}
    lr_options = {0: 0.001, 1: 0.0001, 2: 0.00001}
    conv_layers_options = {0: 2, 1: 3, 2: 4}
    dropout_rate_options = [0.0, 0.2, 0.5]

    iteration_type = iteration % 3
    batch_size = batch_size_options[iteration_type]
    lr = lr_options[iteration_type]
    conv_layers = conv_layers_options[iteration_type]
    dropout_rate = random.choice(dropout_rate_options)

    # Data loading
    train_loader, val_loader = build_train_val_dataloaders(
        metadata_csv=METADATA_FILE,
        audio_dir=DATA_DIR,
        batch_size=batch_size,
        augment=True,
        val_split=0.2,
    )

    # Model setup
    model = BirdCLEFModel(num_classes=NUM_CLASSES, conv_layers=conv_layers, dropout_rate=dropout_rate)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model.to(device)

    criterion = nn.BCELoss()
    optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=1e-4)

    # Training loop
    max_epochs = 20
    early_stopping_patience = 5
    best_auc = 0.0
    epochs_without_improvement = 0

    for epoch in range(max_epochs):
        model.train()
        train_loss = 0.0
        for inputs, labels in tqdm(train_loader):
            inputs, labels = inputs.to(device), labels.to(device)
            
            try:
                optimizer.zero_grad()
                outputs = model(inputs)
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()
                train_loss += loss.item()
            except RuntimeError as e:
                if "out of memory" in str(e):
                    print(f"OOM Error: Reducing batch size from {batch_size} to {batch_size // 2}")
                    torch.cuda.empty_cache()
                    break
                else:
                    raise e

        # Evaluation
        model.eval()
        all_preds = []
        all_labels = []
        with torch.no_grad():
            for inputs, labels in tqdm(val_loader):
                inputs, labels = inputs.to(device), labels.to(device)
                outputs = model(inputs)
                preds = outputs.cpu().numpy()
                all_preds.extend(preds)
                all_labels.extend(labels.cpu().numpy())

        auc = roc_auc_score(all_labels, all_preds, average='weighted')
        print(f"Epoch {epoch+1}, Train Loss: {train_loss/len(train_loader)}, Validation AUC: {auc}")

        if auc > best_auc:
            best_auc = auc
            epochs_without_improvement = 0
        else:
            epochs_without_improvement += 1

        if epochs_without_improvement >= early_stopping_patience:
            print(f"Early stopping at epoch {epoch+1}")
            break

    # Save model and metrics
    torch.save(model.state_dict(), 'model.pt')

    final_train_loss = train_loss / len(train_loader)
    training_samples = len(train_loader.dataset)
    eval_samples = len(val_loader.dataset)
    num_params = sum(p.numel() for p in model.parameters())

    metrics = {
        "final_train_loss": final_train_loss,
        "final_auc": best_auc,
        "num_params": num_params,
        "epochs_trained": epoch + 1,
        "batch_size": batch_size,
        "training_samples": training_samples,
        "eval_samples": eval_samples
    }

    with open('metrics.json', 'w') as f:
        json.dump(metrics, f)
    
    print(f"METRICS: {json.dumps(metrics)}")

# Example usage
iteration = 4  # Change this to the current iteration number
train_model(iteration)